module shortest_cycle_finder (\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] n,\n    input [63:0] graph,\n    output reg done,\n    output reg [2:0] cycle_length,\n    output reg [23:0] cycle\n);\n\n    // State declarations\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] INIT = 3'd1;\n    localparam [2:0] BFS_INIT = 3'd2;\n    localparam [2:0] BFS_PROCESS = 3'd3;\n    localparam [2:0] NEXT_START = 3'd4;\n    localparam [2:0] DONE_STATE = 3'd5;\n\n    reg [2:0] state, next_state;\n    reg [2:0] current_start;\n    reg [2:0] current_distance;\n    reg [7:0] current_set;\n    reg [7:0] next_set;\n    reg [2:0] current_node;\n    reg [2:0] neighbor_idx;\n    reg [7:0] dist [0:7];\n    reg [2:0] parent [0:7];\n    reg [2:0] best_cycle_len;\n    reg [23:0] best_cycle;\n    reg [7:0] clock_counter;\n\n    // Helper wire\n    wire graph_edge = graph[{current_node, neighbor_idx}];\n\n    // State register\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Initialize all registers\n            state <= IDLE;\n            current_start <= 3'd0;\n            current_distance <= 3'd0;\n            current_set <= 8'd0;\n            next_set <= 8'd0;\n            current_node <= 3'd0;\n            neighbor_idx <= 3'd0;\n            best_cycle_len <= 3'd7;\n            best_cycle <= 24'd0;\n            done <= 1'b0;\n            cycle_length <= 3'd0;\n            cycle <= 24'd0;\n            clock_counter <= 8'd0;\n            \n            // Initialize arrays\n            for (integer i = 0; i < 8; i = i + 1) begin\n                dist[i] <= 8'd255;\n                parent[i] <= 3'd0;\n            end\n        end else begin\n            state <= next_state;\n            clock_counter <= clock_counter + 8'd1;\n            \n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    best_cycle_len <= 3'd7;\n                    best_cycle <= 24'd0;\n                    if (start) begin\n                        current_start <= 3'd0;\n                    end\n                end\n                \n                INIT: begin\n                    current_start <= current_start + 3'd1;\n                end\n                \n                BFS_INIT: begin\n                    current_distance <= 3'd0;\n                    current_set <= (8'd1 << current_start);\n                    next_set <= 8'd0;\n                    \n                    for (integer i = 0; i < 8; i = i + 1) begin\n                        dist[i] <= (i == current_start) ? 8'd0 : 8'd255;\n                        parent[i] <= 3'd0;\n                    end\n                end\n                \n                BFS_PROCESS: begin\n                    if (current_set != 8'd0) begin\n                        if (current_node < 3'd7) begin\n                            if (current_set[current_node]) begin\n                                current_set[current_node] <= 1'b0;\n                                neighbor_idx <= 3'd0;\n                            end else begin\n                                current_node <= current_node + 3'd1;\n                            end\n                        end else begin\n                            current_node <= 3'd0;\n                        end\n                    end else begin\n                        current_distance <= current_distance + 3'd1;\n                        current_set <= next_set;\n                        next_set <= 8'd0;\n                    end\n                end\n                \n                NEXT_START: begin\n                    if (current_start >= {1'b0, n} - 3'd1) begin\n                        state <= DONE_STATE;  // Modified this transition\n                    end\n                end\n                \n                DONE_STATE: begin\n                    cycle_length <= best_cycle_len;\n                    cycle <= best_cycle;\n                    done <= 1'b1;\n                end\n            endcase\n            \n            // Node processing logic\n            if (state == BFS_PROCESS && neighbor_idx < n) begin\n                if (graph_edge && dist[current_node] < 8'd255) begin\n                    if (neighbor_idx == current_start && current_distance > 0) begin\n                        if ((current_distance + 1) < best_cycle_len) begin\n                            best_cycle_len <= current_distance + 1;\n                            best_cycle <= {current_start, current_node, parent[current_node]};  // Simplified reconstruction\n                        end\n                    end else if (dist[neighbor_idx] > current_distance + 1) begin\n                        dist[neighbor_idx] <= current_distance + 1;\n                        parent[neighbor_idx] <= current_node;\n                        next_set <= next_set | (8'd1 << neighbor_idx);\n                    end\n                end\n                neighbor_idx <= neighbor_idx + 3'd1;\n            end\n        end\n    end\n    \n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE:          if (start) next_state = BFS_INIT;\n            BFS_INIT:      next_state = BFS_PROCESS;\n            BFS_PROCESS: begin\n                if (current_set == 8'd0 && current_distance >= 3'd7) next_state = NEXT_START;\n                if (clock_counter > 8'd100) next_state = IDLE;  // Safety timeout\n            end\n            NEXT_START:    if (current_start < {1'b0, n} - 3'd1) next_state = BFS_INIT;\n                          else next_state = DONE_STATE;\n            DONE_STATE:    next_state = IDLE;\n            default:       next_state = IDLE;\n        endcase\n    end\nendmodule